// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The simple digital goods (model digital@1): the heading, a description and the goods as a list, each with the
 * format as a pill (PDF, Figma, video course), the name (a link when the good has an address), a line and the
 * price as it is shown. Text only. Axes: layout (cards: a card surface per good in three columns; rows: one row
 * per good, the price at the end from md up).
 */
import { type ReactNode } from "react";
import { Badge, Block, Container, LinkPlain, List, ListItem, Stack, Text, Title } from "../compose";
import { cn, urlOf } from "../utils";
import type { DigitalGood } from "./digital-simple.types";

export type DigitalSimpleProps = {
  id: string;
  title: string;
  description?: string;
  items: DigitalGood[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  layout?: "cards" | "rows";
  landmarkLabel?: string;
};

export function DigitalSimple({
  id,
  title,
  description = "",
  items,
  level = 2,
  padding = "standard",
  align = "center",
  layout = "cards",
  landmarkLabel,
}: DigitalSimpleProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const itemsAlign =
    (align as string) === "center" ? "items-center"
    : (align as string) === "end" ? "items-end"
    : "items-start";
  const selfAlign =
    (align as string) === "center" ? "self-center"
    : (align as string) === "end" ? "self-end"
    : "";
  const grid =
    (layout as string) === "rows" ? "mx-auto max-w-3xl grid-cols-1 gap-4"
    : "grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3";
  const item =
    (layout as string) === "rows" ? "rounded border border-border bg-card p-6 text-card-foreground grid grid-cols-1 items-center gap-4 md:grid-cols-3"
    : "rounded border border-border bg-card p-6 text-card-foreground flex flex-col gap-4";
  const copy = ((layout as string) === "rows") ? "md:col-span-2" : "grow";
  const cost = ((layout as string) === "rows") ? "text-start md:text-end" : "text-start";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="digital-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Stack gap="12" align="stretch">
          <Stack gap="4" align={column} className={cn("max-w-2xl", selfAlign)}>
            <Title as={level} size="3xl" weight="bold" className={cn("tracking-tight", textAlign)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="base" className={cn("text-muted-foreground", textAlign)}>
                {description}
              </Text>
            ) : null}
          </Stack>
          <List tag="ul" className={cn("m-0 w-full list-none p-0", cn("grid", grid))}>
            {(items ?? []).map((g) => (
              <ListItem key={g.id} className={item} data-slot="digital-good">
                <Stack gap="2" align="start" className={copy}>
                  {g.format ? (
                    <Badge variant="outline">
                      {g.format}
                    </Badge>
                  ) : null}
                  {g.href ? (
                    <LinkPlain href={urlOf(g.href)} className="hover:text-primary">
                      <Title as={(level + 1)} size="lg" weight="semibold" className="text-start">
                        {g.title}
                      </Title>
                    </LinkPlain>
                  ) : (
                    <Title as={(level + 1)} size="lg" weight="semibold" className="text-start">
                      {g.title}
                    </Title>
                  )}
                  {g.description ? (
                    <Text size="sm" className={cn("text-muted-foreground", "text-start")}>
                      {g.description}
                    </Text>
                  ) : null}
                </Stack>
                <Text size="base" weight="semibold" className={cn("text-primary", cost)}>
                  {g.price}
                </Text>
              </ListItem>
            ))}
          </List>
        </Stack>
      </Container>
    </Block>
  );
}

